{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "The 20% cap is not necessarily unacceptable in isolation, but its adequacy depends on diligence, warranty coverage, insurance, Seller creditworthiness and the exclusions below."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "a lower de minimis and basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period—24 months is a reasonable opening position"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title, capacity and authority: a cap at least equal to the purchase price and a substantially longer claim period."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Fraud, fraudulent concealment and liabilities that cannot lawfully be excluded: express protection against the limitation and exclusion provisions"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "fair disclosure with sufficient detail to identify the nature and scope of the matter"
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer no Buyer-knowledge exclusion."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make effective change-of-control consent, with all associated conditions satisfied, a Buyer-waivable condition precedent."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "an effective discharge/release arrangement at Completion, supported by binding lender undertakings and subsequent registration evidence."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Allocate sale-triggered liabilities to the Seller through an agreed debt-like/transaction-expense adjustment or Seller-funded payment"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Obtain a specific indemnity for the identified ownership defect, third-party claims and reasonable cure costs—not merely the invoice amount."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for the pre-Completion incident and its consequences, subject to carefully agreed scope and legally recoverable losses."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Neither “ordinary course” nor debt-like treatment can be assumed. Review the three renewals together for timing, scope, commitment, cancellation rights, accruals and commercial benefit."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "More importantly, delete the default extension of limitations to all Claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is relevant evidence, not complete verification of good title."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Do not treat these as “settled” merely because the Seller says so."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

